import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.uw_ZoRon.js";const u=JSON.parse('{"title":"Live attach","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/live-attach.md","filePath":"deep-dive/live-attach.md"}'),r={name:"deep-dive/live-attach.md"};function n(i,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="live-attach" tabindex="-1">Live attach <a class="header-anchor" href="#live-attach" aria-label="Permalink to &quot;Live attach&quot;">​</a></h1><p>One of the BEAM&#39;s best tricks: connect to an <em>already-running</em> node and inspect or poke it live — <code>iex --remsh</code>, or <code>:observer</code> attached to production. RUSM brings this to WebAssembly.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>An attachable node exposes a live <strong>observe channel</strong> over WebSocket. A client that attaches today can:</p><ul><li>watch the live process count and a per-process table (label, registry names, mailbox depth, links) stream in;</li><li>toggle that detail table (<code>detail on|off</code>);</li><li><strong>evaluate JavaScript against the live node</strong> — a stateful shell (bindings persist across lines) with the full <code>Process</code> API, so you can <code>whereis</code> / <code>list</code> / <code>send</code> / <code>kill</code> processes and even <code>connect()</code> to a service live. Gated to <strong>loopback</strong> clients until the channel is authenticated; see <a href="/rusm/deep-dive/the-live-repl">the live REPL</a>;</li><li>(later) hot-reload a module; spawn-through and remote eval over an authenticated channel.</li></ul><p><code>rusm node start</code> serves this channel; the <strong><code>rusm attach &lt;node&gt;</code></strong> REPL renders it in the terminal. The <strong>benchmark dashboard</strong> is a <em>separate</em> node (<code>rusm-bench start</code>, repo-only) with its own richer channel — the scenario-driving observer GUI behind <a href="/rusm/about/benchmark-dashboard-and-observer">the dashboard</a>.</p><h2 id="this-is-new-—-rust-doesn-t-give-it-to-us" tabindex="-1">This is new — Rust doesn&#39;t give it to us <a class="header-anchor" href="#this-is-new-—-rust-doesn-t-give-it-to-us" aria-label="Permalink to &quot;This is new — Rust doesn&#39;t give it to us&quot;">​</a></h2><p>The BEAM bakes remote shell + distribution + observer into the VM. Rust has no runtime VM, no built-in process/node model, and no live introspection, so RUSM builds this itself on the control channel. The closest prior art, <a href="https://github.com/tokio-rs/console" target="_blank" rel="noreferrer"><code>tokio-console</code></a>, is read-mostly diagnostics over a gRPC endpoint — useful inspiration, but not a process-aware REPL you can spawn and message through.</p><h2 id="where-it-stands-phase-9" tabindex="-1">Where it stands (Phase 9) <a class="header-anchor" href="#where-it-stands-phase-9" aria-label="Permalink to &quot;Where it stands (Phase 9)&quot;">​</a></h2><p>Two layers are real:</p><ul><li><strong>Local channel (Phase 0+):</strong> <code>rusm node start</code> serves an observe channel over WebSocket; <code>rusm attach</code> connects to it to watch live process samples and toggle the detail table. (The benchmark dashboard runs the same idea over its own node, <code>rusm-bench start</code>, with scenario controls layered on.)</li><li><strong>Cross-node primitive (Phase 9):</strong> over the cluster transport, a node&#39;s control-plane RPC answers <code>remote_pids(node)</code> — list the processes alive on a <em>peer</em>. That&#39;s the building block behind attaching to a remote node; richer remote introspection (per-process info, message/spawn-through) extends the same RPC.</li></ul><blockquote><p>The transport, control channel, and remote listing are real; the full remote <code>rusm attach &lt;node&gt;</code> REPL surface builds on this primitive.</p></blockquote>',12)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
